        "Flows": "Flows",
        "Flows are what happens without anyone clicking: a reminder before a deadline passes, a confirmation sent on submission. This is where you read and edit them. Nothing to build now.": "Flows zijn wat er gebeurt zonder dat iemand klikt: een herinnering voordat een termijn verstrijkt, een bevestiging bij indiening. Hier lees en bewerk je ze. Je hoeft nu niets te bouwen.",
        "Follow-up": "Opvolging",
        "Follow-up action": "Vervolgactie",
        "Follow-up task": "Opvolgtaak",
        "Follow-ups and meetings created in Pipelinq appear in your Nextcloud Calendar. Calendar events with known contacts are linked to their CRM profile.": "Vervolgacties en vergaderingen die in Pipelinq zijn aangemaakt, verschijnen in uw Nextcloud Agenda. Agendagebeurtenissen met bekende contacten zijn gekoppeld aan hun CRM-profiel.",
        "Followed by us": "Gevolgd door ons",
        "Follower Count": "Aantal volgers",
        "Follower Count Read At": "Volgers gelezen op",
        "Followers": "Volgers",
        "Followers at the last metrics pull, used to turn engagement into a rate rather than a raw count.": "Het aantal volgers bij het laatst ophalen van de cijfers, waarmee interactie een percentage wordt in plaats van een kaal getal.",
        "Follows us": "Volgt ons",
        "Footer Address": "Adres in de voettekst",
        "Footer override": "Aangepaste voettekst",
        "For a Service Level Agreement (SLA), contact": "Voor een Service Level Agreement (SLA), neem contact op met",
        "For a page watch, a hash of the selected fragment as it was last seen. The fragment itself is never stored.": "Bij een paginabewaking een hash van het geselecteerde deel zoals het voor het laatst gezien is. Het deel zelf wordt nooit bewaard.",
        "For a page watch, a hash per line of the fragment as it was last seen, capped. It is what lets the next run say how much was removed without keeping a copy of somebody else's page: the lines that were ADDED are shown from the run's own fresh fetch, and the removed ones are counted, not quoted.": "Bij een paginabewaking een hash per regel van het deel zoals het voor het laatst gezien is, met een maximum. Daarmee kan de volgende keer zeggen hoeveel er weg is zonder een kopie van andermans pagina te bewaren: de regels die erbij kwamen komen uit de verse ophaalactie van die run, en de verdwenen regels worden geteld, niet geciteerd.",
        "For a page watch, the CSS selector of the fragment to compare. A selector that matches nothing is reported rather than silently treated as unchanged.": "Bij een paginabewaking de CSS-selector van het deel dat vergeleken wordt. Een selector die niets vindt wordt gemeld, niet stilzwijgend als ongewijzigd behandeld.",
        "For each attribute with disagreeing sources, choose the authoritative source. Optionally make the choice a persistent trust rule.": "Kies voor elk attribuut met afwijkende bronnen de gezaghebbende bron. Maak de keuze eventueel een blijvende vertrouwensregel.",
        "For support, contact us at": "Voor ondersteuning, neem contact met ons op via",
