        "Hervatten": "Hervatten",
        "Het grootboek, de BTW-boeking en de journaalpost worden beheerd in shillinq. Pipelinq raise alleen de bedrijfsfeiten van deze POS-dag via de integratie-registry.": "Het grootboek, de BTW-boeking en de journaalpost worden beheerd in shillinq. Pipelinq raise alleen de bedrijfsfeiten van deze POS-dag via de integratie-registry.",
