        "Typed email addresses for this client. The legacy single `email` field mirrors the primary entry and stays in sync with it on save.": "Getypeerde e-mailadressen voor deze klant. Het bestaande enkelvoudige veld `email` weerspiegelt het primaire item en blijft daarmee gesynchroniseerd bij het opslaan.",
        "Typed email addresses for this contact person. The legacy single `email` field mirrors the primary entry and stays in sync with it on save.": "Getypeerde e-mailadressen voor deze contactpersoon. Het bestaande enkelvoudige veld `email` weerspiegelt het primaire item en blijft daarmee gesynchroniseerd bij het opslaan.",
        "Typed phone numbers for this client. The legacy single `phone` field mirrors the primary entry and stays in sync with it on save.": "Getypeerde telefoonnummers voor deze klant. Het bestaande enkelvoudige veld `phone` weerspiegelt het primaire item en blijft daarmee gesynchroniseerd bij het opslaan.",
        "Typed phone numbers for this contact person. The legacy single `phone` field mirrors the primary entry and stays in sync with it on save.": "Getypeerde telefoonnummers voor deze contactpersoon. Het bestaande enkelvoudige veld `phone` weerspiegelt het primaire item en blijft daarmee gesynchroniseerd bij het opslaan.",
