        "UID": "UID",
        "URL": "URL",
        "URL-safe identifier, unique within the register. It is what a public page and a link both address, so it is derived from the title once and then left alone.": "Een URL-veilige aanduiding, uniek binnen het register. Een openbare pagina en een link wijzen er allebei naar, dus hij wordt eenmalig uit de titel afgeleid en daarna met rust gelaten.",
        "US Dollar (USD)": "Amerikaanse dollar (USD)",
        "UTM": "UTM",
        "UUID of the credential OpenRegister's broker holds for this account. It is a reference, not a secret: Pipelinq cannot read the token behind it and never tries. Empty until the connect flow returns.": "UUID van de credential die de broker van OpenRegister voor dit account bewaart. Het is een verwijzing en geen geheim: Pipelinq kan het token erachter niet lezen en probeert dat ook niet. Leeg totdat het koppelen klaar is.",
        "UUID of the shillinq `Contract` this sales record belongs to. shillinq owns contract lifecycle (ADR-066), the same cross-app reference the ticket supertype already carries. A plain uuid and not a `$ref`: shillinq's register is a different register, and ADR-062 rule 7 gives a cross-register target a plain string. Empty when shillinq is not installed, in which case this record stands alone on `contractNumber`.": "UUID van het shillinq-`Contract` waar deze verkoopregel bij hoort. Shillinq beheert de contractlevenscyclus (ADR-066), dezelfde koppeling tussen apps die het ticket-supertype al draagt. Een gewone uuid en geen `$ref`: shillinq’s register is een ander register, en ADR-062 regel 7 geeft een doel in een ander register een gewone string. Leeg wanneer shillinq niet is geïnstalleerd; dan staat deze regel op zichzelf op `contractNumber`.",
