        "We corrected {count} of our own ratings on {date}, because we had shipped the capability since the reading. The rival columns are as we read them on the date above.": "Op {date} hebben wij {count} van onze eigen oordelen gecorrigeerd, omdat wij die mogelijkheid sinds de lezing hadden opgeleverd. De andere kolommen staan zoals wij ze op de datum hierboven lazen.",
        "We follow them": "Wij volgen hen",
        "We installed both systems and drove them on {date}. Open source moves fast, so some of these ratings are already out of date. Check that date before you rely on them.": "Wij hebben beide systemen op {date} geïnstalleerd en gebruikt. Open source gaat snel, dus sommige van deze oordelen zijn al verouderd. Kijk naar die datum voordat u erop vertrouwt.",
        "We only compared open source software we could install and run ourselves. Closed and hosted products are not in this table. Their absence is not a verdict on them.": "Wij hebben alleen open source software vergeleken die wij zelf konden installeren en draaien. Gesloten en gehoste producten staan niet in deze tabel. Hun afwezigheid is geen oordeel over hen.",
        "We rated pipelinq and two other help desk systems on {count} capabilities: {systems}.": "Wij hebben pipelinq en twee andere helpdesksystemen op {count} mogelijkheden beoordeeld: {systems}.",
        "We strongly advise you to run your own evaluation. This table does not replace testing against your own requirements.": "Wij raden u dringend aan zelf een evaluatie te doen. Deze tabel vervangt niet het toetsen aan uw eigen eisen.",
