        "Canonical stable UUID key for cross-app references. Defaults to and equals the OpenRegister object UUID. Shillinq stock-keeping and the integration registry use this as the FK: never change it after first write.": "Vaste UUID-sleutel voor verwijzingen tussen apps. Standaard gelijk aan de object-UUID van OpenRegister. De voorraadadministratie van Shillinq en het integratieregister gebruiken hem als verwijzing: wijzig hem nooit na de eerste opslag.",
