        "Discriminator: request (demand/case), complaint (klacht) or contactmoment (logged interaction). Deliberately has NO default: it is `required`, so any create path that forgets to set it fails validation loudly rather than silently filing a complaint or contactmoment as a request. TicketService::save() always stamps it; manifest form dialogs render it as a required choice.": "Onderscheidende waarde: request (verzoek of zaak), complaint (klacht) of contactmoment (vastgelegd contact). Bewust zonder standaardwaarde: het veld is verplicht, zodat elk aanmaakpad dat het vergeet hoorbaar op de validatie stukloopt in plaats van een klacht of contactmoment stil als verzoek weg te schrijven. TicketService::save() zet hem altijd, en de formulieren uit het manifest tonen hem als verplichte keuze.",
