        "Global Trade Item Number (GS1). Supply-side master attribute, distinct from the POS barcode scan field. Format: GTIN-8, GTIN-12 (UPC), GTIN-13 (EAN), or GTIN-14.": "Global Trade Item Number (GS1). Stamgegeven aan de inkoopkant, los van het barcodeveld van de kassa. Formaat: GTIN-8, GTIN-12 (UPC), GTIN-13 (EAN) of GTIN-14.",
