        "Governance decisions raised for this ticket (e.g. Approval/escalation). References decidesk Decision objects (ADR-066); Decidesk owns the making and eIDAS signing. Carried over from the retired `request` schema when it folded into this supertype: the relation belongs to the matter, not to which of the three names it used to have.": "Besluiten die voor dit ticket zijn genomen, bijvoorbeeld een goedkeuring of escalatie. Verwijst naar Decision-objecten in decidesk (ADR-066). Decidesk gaat over het nemen en het eIDAS-ondertekenen. Overgenomen uit het vervallen schema `request` toen dat in dit supertype opging: de relatie hoort bij de zaak, niet bij welke van de drie namen die ooit droeg.",
