        "Object": "Object",
        "Object ID in the source system.": "Object-ID in het bronsysteem.",
        "Object type": "Soort object",
        "Occurred At": "Gebeurd op",
        "One entry per act that filed this contact moment onto a case or took it off one: which case, which act, who performed it and when. Filing is an act rather than a copy, so the trail is the only record that the second case was added by somebody rather than logged there.": "Eén regel per handeling die dit contactmoment op een zaak vastlegde of er weer afhaalde: welke zaak, welke handeling, wie hem uitvoerde en wanneer. Vastleggen is een handeling en geen kopie, dus dit spoor is het enige bewijs dat de tweede zaak door iemand is toegevoegd en niet daar is gelogd.",
        "One entry per close, each with its own version. Reopening and closing again appends rather than overwrites, so two closes leave two snapshots and neither is lost.": "Eén regel per afsluiting, elk met een eigen versie. Opnieuw openen en weer afsluiten voegt toe in plaats van te overschrijven, dus twee afsluitingen laten twee momentopnamen na en geen van beide gaat verloren.",
        "Open Time": "Openingstijd",
        "OpenConnector Endpoint slug for GET betrokkenen (adapter as-built: vng-betrokkenen-list).": "OpenConnector-endpointslug voor GET betrokkenen. In de adapter: vng-betrokkenen-list.",
        "OpenConnector Endpoint slug for GET digitaleadressen (adapter as-built: vng-digitaleadressen-list).": "OpenConnector-endpointslug voor GET digitaleadressen. In de adapter: vng-digitaleadressen-list.",
        "OpenConnector Endpoint slug for GET klantcontacten (adapter as-built: vng-klantcontacten-list).": "OpenConnector-endpointslug voor GET klantcontacten. In de adapter: vng-klantcontacten-list.",
        "OpenConnector Endpoint slug for GET partijen (adapter as-built: vng-partijen-list).": "OpenConnector-endpointslug voor GET partijen. In de adapter: vng-partijen-list.",
        "OpenConnector Endpoint slug for PATCH klantcontacten (adapter as-built: vng-klantcontacten-patch).": "OpenConnector-endpointslug voor PATCH klantcontacten. In de adapter: vng-klantcontacten-patch.",
        "OpenConnector Endpoint slug for POST betrokkenen (adapter as-built: vng-betrokkenen-create).": "OpenConnector-endpointslug voor POST betrokkenen. In de adapter: vng-betrokkenen-create.",
        "OpenConnector Endpoint slug for POST digitaleadressen (adapter as-built: vng-digitaleadressen-create).": "OpenConnector-endpointslug voor POST digitaleadressen. In de adapter: vng-digitaleadressen-create.",
        "OpenConnector Endpoint slug for POST klantcontacten (adapter as-built: vng-klantcontacten-create).": "OpenConnector-endpointslug voor POST klantcontacten. In de adapter: vng-klantcontacten-create.",
        "OpenConnector Endpoint slug for POST partijen (adapter as-built: vng-partijen-create).": "OpenConnector-endpointslug voor POST partijen. In de adapter: vng-partijen-create.",
        "OpenConnector Endpoint slug for PUT klantcontacten (adapter as-built: vng-klantcontacten-update).": "OpenConnector-endpointslug voor PUT klantcontacten. In de adapter: vng-klantcontacten-update.",
        "OpenConnector Endpoint slug for the composite POST maak-klantcontact (adapter as-built: vng-maak-klantcontact).": "OpenConnector-endpointslug voor de samengestelde POST maak-klantcontact. In de adapter: vng-maak-klantcontact.",
        "OpenConnector Rule slug adding self-URL/HAL links to responses (adapter as-built: vng-selfurl-hal).": "OpenConnector-regelslug die self-URL- en HAL-links aan antwoorden toevoegt. In de adapter: vng-selfurl-hal.",
        "OpenConnector Rule slug enforcing inbound AVG BSN hashing (before-timing; adapter as-built: vng-avg-bsn-policy). See vng-klantinteracties-leaf AVG BSN policy requirement.": "OpenConnector-regelslug die inkomende BSN's volgens de AVG hasht, met timing before. In de adapter: vng-avg-bsn-policy. Zie de AVG-BSN-eis van de vng-klantinteracties-leaf.",
        "OpenConnector Rule slug generating the scheme-overridable UUIDv4 referentienummer (adapter as-built: vng-referentienummer).": "OpenConnector-regelslug die het UUIDv4-referentienummer genereert, dat per schema overschreven kan worden. In de adapter: vng-referentienummer.",
        "OpenConnector Rule slug guarding outbound responses against raw-BSN reconstruction (after-timing; adapter as-built: vng-avg-bsn-policy-outbound-guard). Not in this leaf's original design: the adapter split AVG BSN handling into two Rule objects because its `rule.timing` property is single-valued.": "OpenConnector-regelslug die uitgaande antwoorden behoedt voor het terugrekenen van een BSN, met timing after. In de adapter: vng-avg-bsn-policy-outbound-guard. Dit zat niet in het oorspronkelijke ontwerp van deze leaf: de adapter splitste de AVG-BSN-afhandeling in twee Rule-objecten omdat `rule.timing` maar één waarde kan hebben.",
        "OpenConnector Rule slug that fans out the composite maak-klantcontact write (adapter as-built: vng-maak-klantcontact-composite).": "OpenConnector-regelslug die de samengestelde schrijfactie maak-klantcontact uiteenzet. In de adapter: vng-maak-klantcontact-composite.",
        "OpenConnector source slug that transports this provider (e.g. messagebird-sms, cmcom-sms, twilio-sms, whatsapp-cloud-api, whatsapp-bsp). Credentials and base URL live on that source; this row carries routing metadata only.": "Slug van de OpenConnector-bron die het verkeer voor deze provider verzorgt, bijvoorbeeld messagebird-sms, cmcom-sms, twilio-sms, whatsapp-cloud-api of whatsapp-bsp. De inloggegevens en de basis-URL staan op die bron. Deze regel bevat alleen routeringsgegevens.",
        "OpenConnector source UUID/slug that stores the platform credentials.": "UUID of slug van de OpenConnector-bron waar de inloggegevens van het platform staan.",
        "Opened At": "Geopend op",
