        "Optional breakdown by denomination, e.g. [{denomination: EUR_50, quantity: 2, subtotal: 100.00}]": "Optionele verdeling per coupure, bijvoorbeeld [{denomination: EUR_50, quantity: 2, subtotal: 100.00}]",
