        "Optional JSON filter (category, excludeCategory, segment, dayOfWeek, timeRange, channel).": "Optioneel JSON-filter met category, excludeCategory, segment, dayOfWeek, timeRange en channel.",
        "Optional line-level notes, e.g. inclusief montage": "Optionele notities bij de regel, bijvoorbeeld inclusief montage",
        "Optional Nextcloud user id for staff resources (for self-management of working hours).": "Optionele Nextcloud-gebruikers-id bij resources die medewerkers zijn, zodat zij hun werktijden zelf kunnen beheren.",
        "Optional Nextcloud user UID linking this operator to an NC account": "Optionele Nextcloud-gebruikers-UID die deze medewerker aan een Nextcloud-account koppelt",
