        "Optional partitioning expression, e.g. created_at:day.": "Optionele partitie-expressie, bijvoorbeeld created_at:day.",
        "Optional per-customer override. Null = all customers within tier.": "Optionele afwijking per klant. Null betekent alle klanten binnen het niveau.",
