        "Projection of the shillinq journal-entry outcome for this POS day. pending = raise queued / shillinq unreachable; raised = shillinq accepted and returned a journal id; failed = the registry raise exhausted its retries. The GL chart, the VAT posting and the journal itself live in shillinq (cross-app contract #3); this is only a read-only status mirror so operators can see whether the day is booked.": "Weergave van de uitkomst van de shillinq-journaalpost voor deze kassadag. pending betekent dat de boeking in de wachtrij staat of shillinq onbereikbaar is, raised dat shillinq hem accepteerde en een journaal-id teruggaf, en failed dat het register zijn pogingen heeft opgebruikt. Het rekeningschema, de btw-boeking en het journaal zelf staan in shillinq (contract 3 tussen apps). Dit is alleen een alleen-lezen statusspiegel, zodat medewerkers kunnen zien of de dag geboekt is.",
