        "Sequence of steps for composite services (e.g. colour application + processing gap + cut). Empty for single-step services.": "Volgorde van stappen bij samengestelde diensten, bijvoorbeeld kleuren, inwerktijd en knippen. Leeg bij diensten met één stap.",
        "Serial": "Serienummer",
        "Server-allocated legal invoice number (e.g. 2026-000042) assigned once when a receipt is issued for a transaction >= EUR 100. Never accepted from the client; allocated race-safe by InvoiceSequenceService.": "Wettelijk factuurnummer dat de server toekent, bijvoorbeeld 2026-000042. Wordt eenmalig gegeven bij een bon voor een transactie van 100 euro of meer. Nooit van de client overgenomen: InvoiceSequenceService kent het toe zonder dat twee bonnen hetzelfde nummer kunnen krijgen.",
        "Server-computed (diffAmount / expectedAmount) * 100; null when expectedAmount is 0": "Door de server berekend als (diffAmount / expectedAmount) * 100. Null als expectedAmount 0 is.",
        "Server-computed actualAmount - expectedAmount (negative = shortage, positive = overage)": "Door de server berekend als actualAmount min expectedAmount. Negatief is een tekort, positief een overschot.",
        "Server-computed expected cash: floatAmount + salesTotal - dropsTotal": "Door de server berekend verwacht kasgeld: floatAmount plus salesTotal min dropsTotal",
        "Server-issued legal invoice number recorded with this action (empty for non-invoice receipts). Used to prove a number on a transaction was server-issued, not client-forged.": "Wettelijk factuurnummer dat de server uitgaf en dat bij deze handeling is vastgelegd. Leeg bij bonnen zonder factuurnummer. Hiermee is aan te tonen dat een nummer van de server komt en niet door de client is verzonnen.",
        "Service Duration": "Duur van de dienst",
        "Service duration in minutes (behandelingen, afspraken). Relevant when type=service.": "Duur van de dienst in minuten, bij behandelingen en afspraken. Van belang als type gelijk is aan service.",
