        "Set when the one-per-period soft-alert has fired; cleared on reset.": "Gezet zodra de zachte waarschuwing van deze periode is afgegaan. Gaat leeg bij het opnieuw starten van de periode.",
        "Set when timer is paused (null when running).": "Gezet wanneer de teller gepauzeerd is. Null zolang hij loopt.",
