        "Severity": "Ernst",
        "SHA-256 hash of the message body at event time (integrity).": "SHA-256-hash van de berichtinhoud op het moment van de gebeurtenis, voor de integriteit.",
        "SHA-256 hash of the session token.": "SHA-256-hash van het sessietoken.",
        "SHA-256 hash van BSN (NOOIT raw BSN persistent). Hex-string van 64 chars.": "SHA-256-hash van het BSN. Een BSN wordt nooit leesbaar opgeslagen. Hexadecimale tekst van 64 tekens.",
        "SHA-256 hash van BSN (NOOIT raw). Hex-string van 64 chars.": "SHA-256-hash van het BSN, nooit leesbaar. Hexadecimale tekst van 64 tekens.",
        "SHA-256 hash van BSN (NOOIT raw). Hex-string van 64 chars. Gepseudonimiseerd na RTBF.": "SHA-256-hash van het BSN, nooit leesbaar. Hexadecimale tekst van 64 tekens. Wordt na een verwijderverzoek gepseudonimiseerd.",
        "SHA-256 hash van het BSN (NOOIT raw BSN). Hex-string van 64 chars.": "SHA-256-hash van het BSN, dat nooit leesbaar wordt opgeslagen. Hexadecimale tekst van 64 tekens.",
        "SHA-256 hex digest of the prior entry's currentHash for this register, or '0' for the genesis entry": "SHA-256-hexdigest van de currentHash van de vorige regel voor deze kassa, of '0' bij de allereerste regel",
        "SHA-256 hex digest of this entry's canonicalised fields + previousHash; used to chain the next entry": "SHA-256-hexdigest van de genormaliseerde velden van deze regel plus previousHash, waarmee de volgende regel wordt aangehaakt",
        "Shared HMAC secret used to verify inbound webhooks.": "Gedeeld HMAC-geheim waarmee binnenkomende webhooks worden gecontroleerd.",
        "Shift status": "Status van de dienst",
        "Shillinq AP sync state for this expense (null until the first approval event)..": "Synchronisatiestatus met de crediteurenadministratie van Shillinq voor deze uitgave. Null tot de eerste goedkeuring.",
        "Shillinq Journal Entry ID": "Shillinq-journaalpost-ID",
        "Shillinq Organisation Reference": "Shillinq-organisatieverwijzing",
        "Shillinq time-intake billing handoff state (time-billing-handoff-emit). Unset until the first 'Send to billing' attempt for the batch this entry belongs to. pending = marked before the intake call; synced = the batch was accepted (billingInvoiceId set); failed = a transient/transport error, retried by BillingHandoffRetryJob's re-notification and a manual re-send.": "Status van de urenoverdracht naar de facturatie van Shillinq (time-billing-handoff-emit). Blijft leeg tot de eerste poging om de batch waar deze regel bij hoort naar de facturatie te sturen. pending is gezet vlak voor de aanroep, synced betekent dat de batch is geaccepteerd en billingInvoiceId is gevuld, en failed staat voor een tijdelijke fout die BillingHandoffRetryJob opnieuw aanbiedt en die handmatig opnieuw verstuurd kan worden.",
        "Shillinq WIP sync state. Null for entries approved before the WIP integration was deployed.": "Synchronisatiestatus van het onderhanden werk met Shillinq. Null bij regels die zijn goedgekeurd voordat die koppeling in gebruik werd genomen.",
        "Short human-readable label for the time entry.": "Korte leesbare aanduiding van de urenregel.",
        "Short machine-readable identifier (e.g. BILL, WBSO, DBA). Should be unique per active category.": "Korte machineleesbare aanduiding, bijvoorbeeld BILL, WBSO of DBA. Hoort uniek te zijn per actieve categorie.",
        "Short title for the expense (schema:name).": "Korte titel van de uitgave (schema:name).",
        "Signature Valid": "Handtekening geldig",
        "Signed delta. Credit positive, debit/expiry negative, adjustment signed.": "Mutatie met teken. Bijschrijven is positief, afschrijven en vervallen negatief, en een correctie kan beide zijn.",
