        "State change being audited (indexed).": "Statuswijziging die wordt vastgelegd, geïndexeerd.",
        "Status after the transition.": "Status na de overgang.",
        "Status History": "Statushistorie",
        "Status label materialised by OpenRegister from qualityScore (good/fair/poor).": "Statuslabel dat OpenRegister afleidt uit qualityScore: goed, redelijk of slecht.",
        "Status of the last marketingConsent sync to the linked pipelinq contact: 'pending' (no sync attempted yet), 'success', 'skipped' (do-not-contact), or 'failed'. Defaults to 'pending' rather than an empty string: OpenRegister coerces a stored empty string back to null, and the TransitionEngine's whole-object re-save (confirm/settle/refund/park/resume) then fails strict validation with \"should be type 'string' but is 'null'\". A non-empty default persists and keeps the lifecycle transitions working.": "Status van de laatste synchronisatie van marketingConsent naar de gekoppelde pipelinq-contactpersoon: 'pending' als er nog niets is geprobeerd, 'success', 'skipped' bij niet benaderen, of 'failed'. De standaardwaarde is 'pending' en niet een lege tekst, omdat OpenRegister een opgeslagen lege tekst terugzet naar null. De TransitionEngine slaat bij bevestigen, afrekenen, terugbetalen, parkeren en hervatten het hele object opnieuw op en loopt dan vast op \"should be type 'string' but is 'null'\". Een niet-lege standaardwaarde blijft staan en houdt de overgangen werkend.",
        "Status transitions are sequential.": "Statusovergangen volgen elkaar op.",
        "Status values that pause the timer (e.g. ['awaiting-customer', 'on-hold']).": "Statussen die de teller pauzeren, bijvoorbeeld ['awaiting-customer', 'on-hold'].",
