        "UUID of the Master Entity this contact maps to (MDM). Null for legacy / un-linked contacts.": "UUID van het hoofdobject waar deze contactpersoon bij hoort in het stamgegevensbeheer. Null bij oude of niet-gekoppelde contactpersonen.",
        "UUID of the Master Entity this product maps to (MDM). Null for legacy / un-linked products.": "UUID van het hoofdobject waar dit product bij hoort in het stamgegevensbeheer. Null bij oude of niet-gekoppelde producten.",
