        "UUID reference to a refundReason for this specific item": "UUID-verwijzing naar een refundReason voor dit artikel",
        "UUID reference to an exportDestination.": "UUID-verwijzing naar een exportDestination.",
        "UUID reference to an OpenConnector source holding the credentials. Credentials are never stored on this object.": "UUID-verwijzing naar een OpenConnector-bron waar de inloggegevens staan. Op dit object worden nooit inloggegevens bewaard.",
        "UUID reference to parent category (for hierarchy)": "UUID-verwijzing naar de bovenliggende categorie, voor de hiërarchie",
        "UUID reference to the associated client": "UUID-verwijzing naar de bijbehorende klant",
        "UUID reference to the associated client.": "UUID-verwijzing naar de bijbehorende klant.",
        "UUID reference to the associated contact person": "UUID-verwijzing naar de bijbehorende contactpersoon",
        "UUID reference to the associated contact person.": "UUID-verwijzing naar de bijbehorende contactpersoon.",
        "UUID reference to the associated request. Requests were folded into the `ticket` supertype by 99-unify-ticket-supertype, so this resolves to a ticket; the property keeps its stored name because renaming it would be a data migration.": "UUID-verwijzing naar het bijbehorende verzoek. Verzoeken zijn met 99-unify-ticket-supertype opgegaan in het supertype `ticket`, dus dit wijst naar een ticket. De eigenschap houdt haar opgeslagen naam, omdat hernoemen een gegevensmigratie zou vergen.",
        "UUID reference to the deal this task belongs to. Set automatically when the task is created from the Tasks tab on a lead — the object-list widget merges its resolved filter into the create payload, so the deal is pre-linked without the user picking it. A task may hang off a client, a request or a deal; the three are independent.": "UUID-verwijzing naar de deal waar deze taak bij hoort. Wordt automatisch gezet als de taak vanaf het tabblad Taken op een lead wordt aangemaakt: de objectlijst voegt haar filter toe aan de aanmaakgegevens, zodat de deal al gekoppeld is zonder dat de gebruiker hem kiest. Een taak kan onder een klant, een verzoek of een deal hangen, en die drie staan los van elkaar.",
        "UUID reference to the deal this ticket belongs to. Carries a contactmoment (ticketType `interaction`) logged while working a deal, so the conversation history sits with the deal rather than only with the account. NO `x-relation-filter` scoping the picker to the ticket's own client, deliberately: gate-54 resolves an `@object.<field>` token against the properties declared in the FILE it reads, and this is a partial overlay that declares only `lead`, so `@object.client` is unresolvable here however real `ticket.client` is in the assembled schema.": "UUID-verwijzing naar de deal waar dit ticket bij hoort. Draagt een contactmoment (ticketType `interaction`) dat tijdens het werken aan een deal is vastgelegd, zodat de gesprekshistorie bij de deal staat en niet alleen bij het account. Bewust geen `x-relation-filter` die de keuzelijst tot de klant van het ticket beperkt: gate-54 lost een `@object.<field>`-token op tegen de eigenschappen in het bestand dat het leest, en dit is een gedeeltelijke aanvulling die alleen `lead` declareert. `@object.client` is hier dus niet op te lossen, hoe echt `ticket.client` in het samengestelde schema ook is.",
        "UUID reference to the existing client object. Client identity is never duplicated into the contract.": "UUID-verwijzing naar het bestaande klantobject. De identiteit van de klant wordt nooit in het contract gekopieerd.",
        "UUID reference to the exportJob.": "UUID-verwijzing naar de exportJob.",
