        "When mapped attributes last changed; used for freshness decay.": "Wanneer de gekoppelde kenmerken voor het laatst wijzigden. Wordt gebruikt om de versheid te laten afnemen.",
        "When successfully delivered to Berichtenbox.": "Wanneer het met succes in de Berichtenbox is afgeleverd.",
        "When that confirmation happened.": "Wanneer die bevestiging plaatsvond.",
