        "When the complaint was resolved (complaint only).": "Wanneer de klacht is afgehandeld. Alleen bij een klacht.",
        "When the delay elapses and the invitation may be sent.": "Wanneer de wachttijd voorbij is en de uitnodiging verstuurd mag worden.",
