        "When the matter was raised (request.requestedAt) or the interaction happened (contactmoment.contactedAt).": "Wanneer de zaak is aangemeld (request.requestedAt) of het contact plaatsvond (contactmoment.contactedAt).",
        "When the next dispatch attempt is eligible (exponential backoff).": "Wanneer de volgende verzendpoging aan de beurt is, met een oplopende wachttijd.",
        "When the party started holding this kind on this record.": "Wanneer de partij deze soort op dit record ging houden.",
